//! Blend and compositing math, matching CSP 1.13.2 as observed (DECISIONS D-017).
//!
//! Sources: specs L-001 (opaque results), L-002 (source alpha), L-003 (layer opacity),
//! L-005 (semi-transparent backdrop), L-007 (non-separable modes).
//!
//! - Separable modes with a known exact formula are integer code (19 of 22).
//! - Overlay, Hard light and Vivid light use the **observed 256×256 tables** (`tables/*.bin`,
//!   generated by `tools/observe/make_blend_tables.py` from the spec data).
//! - Soft light uses the W3C float formula with round-half-to-even, which reproduces L-001
//!   bit-exactly. Like the non-separable clip step, it uses only IEEE `+ - * / sqrt` (correctly
//!   rounded, so identical on every platform; D-012).
//! - Open cases (see the specs) are implemented with the closest known model; their tests carry
//!   stated tolerances.

use super::BlendMode;

static OVERLAY: &[u8; 65536] = include_bytes!("tables/overlay.bin");
static HARD_LIGHT: &[u8; 65536] = include_bytes!("tables/hard_light.bin");
static VIVID_LIGHT: &[u8; 65536] = include_bytes!("tables/vivid_light.bin");

fn table(t: &[u8; 65536], b: u8, s: u8) -> u8 {
    t[usize::from(b) * 256 + usize::from(s)]
}

fn clamp8(v: i32) -> u8 {
    v.clamp(0, 255) as u8
}

fn mul(b: u32, s: u32) -> u32 {
    (b * s + 127) / 255
}

/// Color burn (L-001): floor division, then clamp.
fn burn(b: u8, s: u8) -> u8 {
    match (b, s) {
        (255, _) => 255,
        (_, 0) => 0,
        _ => clamp8(255 - ((255 - i32::from(b)) * 255) / i32::from(s)),
    }
}

/// Color dodge (L-001): floor division, then clamp.
fn dodge(b: u8, s: u8) -> u8 {
    match (b, s) {
        (0, _) => 0,
        (_, 255) => 255,
        _ => (u32::from(b) * 255 / (255 - u32::from(s))).min(255) as u8,
    }
}

fn soft_light(b: u8, s: u8) -> u8 {
    let fb = f64::from(b) / 255.0;
    let fs = f64::from(s) / 255.0;
    let r = if fs <= 0.5 {
        fb - (1.0 - 2.0 * fs) * fb * (1.0 - fb)
    } else {
        let d = if fb <= 0.25 {
            ((16.0 * fb - 12.0) * fb + 4.0) * fb
        } else {
            fb.sqrt()
        };
        fb + (2.0 * fs - 1.0) * (d - fb)
    };
    (r * 255.0).round_ties_even().clamp(0.0, 255.0) as u8
}

/// Result of a separable mode for one channel: backdrop `b`, source `s` (both opaque).
/// Non-separable modes are handled by [`blend_rgb`]; here they fall back to Normal.
pub fn blend_channel(mode: BlendMode, b: u8, s: u8) -> u8 {
    use BlendMode as M;
    let (bi, si) = (i32::from(b), i32::from(s));
    let (bu, su) = (u32::from(b), u32::from(s));
    match mode {
        M::Normal
        | M::DarkerColor
        | M::LighterColor
        | M::Hue
        | M::Saturation
        | M::Color
        | M::Brightness => s,
        M::Darken => b.min(s),
        M::Multiply => mul(bu, su) as u8,
        M::ColorBurn => burn(b, s),
        M::LinearBurn => clamp8(bi + si - 255),
        M::Subtract => clamp8(bi - si),
        M::Lighten => b.max(s),
        M::Screen => (bu + su - mul(bu, su)) as u8,
        M::ColorDodge | M::GlowDodge => dodge(b, s),
        M::Add | M::AddGlow => clamp8(bi + si),
        M::Overlay => table(OVERLAY, b, s),
        M::SoftLight => soft_light(b, s),
        M::HardLight => table(HARD_LIGHT, b, s),
        M::Difference => b.abs_diff(s),
        M::VividLight => table(VIVID_LIGHT, b, s),
        M::LinearLight => clamp8(bi + 2 * si - 255),
        M::PinLight => {
            if s < 128 {
                b.min(clamp8(2 * si))
            } else {
                b.max(clamp8(2 * si - 255))
            }
        }
        M::HardMix => {
            let on = if s < 128 {
                bi + si >= 255
            } else {
                bi + si > 255
            };
            if on { 255 } else { 0 }
        }
        M::Exclusion => (bu + su - (2 * bu * su + 127) / 255) as u8,
        M::Divide => {
            if s == 0 {
                if b > 0 { 255 } else { 0 }
            } else {
                ((bu * 255 + su / 2) / su).min(255) as u8
            }
        }
    }
}

/// Integer luma (L-007): round((30R + 59G + 11B) / 100).
pub fn luma(c: [u8; 3]) -> i32 {
    (30 * i32::from(c[0]) + 59 * i32::from(c[1]) + 11 * i32::from(c[2]) + 50) / 100
}

fn sat(c: [u8; 3]) -> i32 {
    i32::from(c[0].max(c[1]).max(c[2])) - i32::from(c[0].min(c[1]).min(c[2]))
}

/// Integer SetSat (L-007): scale the colour's range to `s`, rounded.
fn set_sat(c: [u8; 3], s: i32) -> [i32; 3] {
    let mn = i32::from(c[0].min(c[1]).min(c[2]));
    let r = sat(c);
    if r == 0 {
        return [0; 3];
    }
    c.map(|v| ((i32::from(v) - mn) * s + r / 2) / r)
}

/// SetLum with W3C ClipColor towards luma `l` (closest known model for the clip step, L-007).
fn set_lum(c: [i32; 3], l: i32) -> [u8; 3] {
    let lc = (30 * c[0] + 59 * c[1] + 11 * c[2] + 50) / 100;
    let d = l - lc;
    let c = c.map(|v| f64::from(v + d));
    let lf = f64::from(l);
    let n = c[0].min(c[1]).min(c[2]);
    let x = c[0].max(c[1]).max(c[2]);
    let c = if n < 0.0 {
        c.map(|v| lf + (v - lf) * lf / (lf - n))
    } else {
        c
    };
    let c = if x > 255.0 {
        c.map(|v| lf + (v - lf) * (255.0 - lf) / (x - lf))
    } else {
        c
    };
    c.map(|v| v.round_ties_even().clamp(0.0, 255.0) as u8)
}

/// Result of any mode for one opaque pixel: backdrop `b`, source `s`.
pub fn blend_rgb(mode: BlendMode, b: [u8; 3], s: [u8; 3]) -> [u8; 3] {
    use BlendMode as M;
    match mode {
        // Whole-pixel pick on integer luma; ties go to the top layer (L-007).
        M::DarkerColor => {
            if luma(s) <= luma(b) {
                s
            } else {
                b
            }
        }
        M::LighterColor => {
            if luma(s) >= luma(b) {
                s
            } else {
                b
            }
        }
        M::Hue => set_lum(set_sat(s, sat(b)), luma(b)),
        M::Saturation => set_lum(set_sat(b, sat(s)), luma(b)),
        M::Color => set_lum(s.map(i32::from), luma(b)),
        M::Brightness => set_lum(b.map(i32::from), luma(s)),
        _ => [0, 1, 2].map(|i| blend_channel(mode, b[i], s[i])),
    }
}

/// 8-bit alpha to the 15-bit scale used for compositing (L-002).
pub fn a15(a: u8) -> u32 {
    (u32::from(a) * 32768 + 127) / 255
}

/// Per-pixel alpha `a` combined with layer opacity in percent (L-003).
pub fn effective_alpha(a: u8, opacity_pct: u8) -> u8 {
    let o8 = u32::from(opacity_pct.min(100)) * 255 / 100;
    ((u32::from(a) * (o8 + 1)) >> 8) as u8
}

fn is_glow(mode: BlendMode) -> bool {
    matches!(mode, BlendMode::AddGlow | BlendMode::GlowDodge)
}

/// Composite a source pixel with effective alpha `a` over an **opaque** backdrop (L-002):
/// a 15-bit lerp from the backdrop to the blend result; the Glow modes premultiply the
/// source by alpha instead.
pub fn over_opaque(mode: BlendMode, b: [u8; 3], s: [u8; 3], a: u8) -> [u8; 3] {
    let w = a15(a);
    if is_glow(mode) {
        let pm = s.map(|v| ((u32::from(v) * w + 16384) >> 15) as u8);
        return [0, 1, 2].map(|i| blend_channel(mode, b[i], pm[i]));
    }
    let r = blend_rgb(mode, b, s);
    [0, 1, 2].map(|i| ((u32::from(b[i]) * (32768 - w) + u32::from(r[i]) * w + 16384) >> 15) as u8)
}

/// Output alpha over a semi-transparent backdrop (L-005; exact for all 28 modes).
pub fn out_alpha(mode: BlendMode, ab: u8, at: u8) -> u8 {
    use BlendMode as M;
    let (ab, at) = (u32::from(ab), u32::from(at));
    let v = match mode {
        M::Normal => (ab * (32768 - a15(at as u8)) + 255 * a15(at as u8)) >> 15,
        M::Screen | M::ColorDodge | M::GlowDodge | M::SoftLight | M::HardLight => {
            (at + ab).min(255)
        }
        _ => at + (ab * (255 - at) + 127) / 255,
    };
    v.min(255) as u8
}

/// Composite a source pixel (colour `s`, effective alpha `at`) over a backdrop with alpha
/// (straight RGBA). Exact for an opaque backdrop (L-002) and for output alpha in every case
/// (L-005). Colour over a semi-transparent backdrop: Normal per L-005 (99.6 % exact, ±1);
/// other modes use the W3C general rule (open, see L-005).
pub fn composite(mode: BlendMode, b: [u8; 4], s: [u8; 3], at: u8) -> [u8; 4] {
    let ab = b[3];
    let rgb_b = [b[0], b[1], b[2]];
    if ab == 255 {
        let c = over_opaque(mode, rgb_b, s, at);
        return [c[0], c[1], c[2], 255];
    }
    let ao = out_alpha(mode, ab, at);
    if ao == 0 {
        return [0; 4];
    }
    let (ao32, at32) = (u32::from(ao), u32::from(at));
    let wb = ao32.saturating_sub(at32);
    let src = if mode == BlendMode::Normal || ab == 0 {
        s
    } else {
        // W3C: mix the source towards B(b, s) by the backdrop alpha.
        let r = blend_rgb(mode, rgb_b, s);
        [0, 1, 2].map(|i| {
            ((u32::from(s[i]) * (255 - u32::from(ab)) + u32::from(r[i]) * u32::from(ab) + 127)
                / 255) as u8
        })
    };
    let c = [0, 1, 2].map(|i| {
        ((u32::from(src[i]) * at32 + u32::from(rgb_b[i]) * wb + ao32 / 2) / ao32).min(255) as u8
    });
    [c[0], c[1], c[2], ao]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn spot_values_from_specs() {
        // L-001 examples and edge rules.
        assert_eq!(blend_channel(BlendMode::Divide, 0, 0), 0);
        assert_eq!(blend_channel(BlendMode::Divide, 1, 0), 255);
        assert_eq!(blend_channel(BlendMode::Divide, 1, 6), 43);
        assert_eq!(blend_channel(BlendMode::HardMix, 127, 128), 0);
        assert_eq!(blend_channel(BlendMode::HardMix, 128, 127), 255);
        assert_eq!(blend_channel(BlendMode::ColorDodge, 0, 255), 0);
        // L-003: 1 % opacity → o8 = 2.
        assert_eq!(effective_alpha(255, 1), 2);
        assert_eq!(effective_alpha(255, 100), 255);
        assert_eq!(effective_alpha(200, 100), 200);
        // L-007 example: Hue of base (255,0,0) with top (0,30,200) — CSP gives (35,68,255);
        // the W3C clip model gives (32,66,255) (open question, within the stated tolerance).
        let h = blend_rgb(BlendMode::Hue, [255, 0, 0], [0, 30, 200]);
        assert!(
            h.iter().zip([35, 68, 255]).all(|(a, b)| a.abs_diff(b) <= 6),
            "{h:?}"
        );
    }

    #[test]
    fn composite_reduces_to_simpler_cases() {
        for &m in BlendMode::ALL {
            // Fully transparent source leaves the backdrop unchanged.
            assert_eq!(
                composite(m, [10, 20, 30, 200], [250, 0, 0], 0),
                [10, 20, 30, 200],
                "{m:?}"
            );
            // Opaque backdrop: alpha stays 255.
            assert_eq!(
                composite(m, [10, 20, 30, 255], [250, 0, 0], 77)[3],
                255,
                "{m:?}"
            );
        }
        // Empty backdrop: Normal gives the source colour. Its alpha follows L-005's 15-bit
        // floor lerp, which CSP really does: alpha 100 comes out as 99.
        assert_eq!(
            composite(BlendMode::Normal, [0; 4], [9, 8, 7], 100),
            [9, 8, 7, 99]
        );
        assert_eq!(
            composite(BlendMode::Normal, [0; 4], [9, 8, 7], 255),
            [9, 8, 7, 255]
        );
    }
}
